inline const OPM *GetOPM(const void *buf) {
  return ::flatbuffers::GetRoot<OPM>(buf);
}

inline const OPM *GetSizePrefixedOPM(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<OPM>(buf);
}

inline const char *OPMIdentifier() {
  return "$OPM";
}

inline bool OPMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, OPMIdentifier());
}

inline bool SizePrefixedOPMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, OPMIdentifier(), true);
}

template <bool B = false>
inline bool VerifyOPMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<OPM>(OPMIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedOPMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<OPM>(OPMIdentifier());
}

inline void FinishOPMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<OPM> root) {
  fbb.Finish(root, OPMIdentifier());
}

inline void FinishSizePrefixedOPMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<OPM> root) {
  fbb.FinishSizePrefixed(root, OPMIdentifier());
}

inline std::unique_ptr<OPMT> UnPackOPM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<OPMT>(GetOPM(buf)->UnPack(res));
}

inline std::unique_ptr<OPMT> UnPackSizePrefixedOPM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<OPMT>(GetSizePrefixedOPM(buf)->UnPack(res));
}

